_MANIFEST_FIELDS = {
    "schema_version",
    "id",
    "prompt",
    "max_steps",
    "editable_paths",
}
_PACKAGE_TOP_LEVEL = {"task.json", "workspace", "held_out_tests"}
_MAX_FILES = 1_000
_MAX_DIRECTORIES = 512
_MAX_DEPTH = 64
_MAX_DIRECTORY_ENTRIES = _MAX_FILES + _MAX_DIRECTORIES
_MAX_FILE_BYTES = 1024 * 1024
_MAX_TREE_BYTES = 16 * 1024 * 1024
_MAX_CHECKS = 256
_MAX_STRING_CHARS = 256 * 1024
_EXECUTABLE_BITS = stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH
_DIRECTORY_FLAGS = (
    os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_NOFOLLOW", 0)
)


