def _identity(status: os.stat_result) -> tuple[int, int]:
    return status.st_dev, status.st_ino


def _is_infrastructure(relative: PurePosixPath) -> bool:
    for part in relative.parts:
        lower = part.casefold()
        if (
            lower == ".tiny-llm"
            or lower.startswith(".tiny-llm-agent-")
            or lower.startswith(".tiny-llm-undo-")
        ):
            return True
    return False


def _validate_tree_name(relative: PurePosixPath) -> None:
    if any(part.casefold() == ".git" for part in relative.parts):
        raise ValueError(".git metadata is not allowed in an evaluation tree")


def _read_open_regular(
    parent: int,
    name: str,
    expected: os.stat_result,
    *,
    limit: int,
    label: str,
) -> bytes:
    flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)
    try:
        descriptor = os.open(name, flags, dir_fd=parent)
    except OSError as error:
        raise ValueError(f"{label} is unsafe") from error
    try:
        before = os.fstat(descriptor)
        expected_fields = (
            expected.st_dev,
            expected.st_ino,
            expected.st_mode,
            expected.st_nlink,
            expected.st_size,
            expected.st_mtime_ns,
            expected.st_ctime_ns,
        )
        before_fields = (
            before.st_dev,
            before.st_ino,
            before.st_mode,
            before.st_nlink,
            before.st_size,
            before.st_mtime_ns,
            before.st_ctime_ns,
        )
        if (
            not stat.S_ISREG(before.st_mode)
            or before.st_nlink != 1
            or before.st_size > limit
            or before_fields != expected_fields
        ):
            raise ValueError(f"{label} is not a bounded regular file")
        chunks: list[bytes] = []
        remaining = limit + 1
        while remaining:
            chunk = os.read(descriptor, min(64 * 1024, remaining))
            if not chunk:
                break
            chunks.append(chunk)
            remaining -= len(chunk)
        content = b"".join(chunks)
        after = os.fstat(descriptor)
        stable_fields = before_fields
        after_fields = (
            after.st_dev,
            after.st_ino,
            after.st_mode,
            after.st_nlink,
            after.st_size,
            after.st_mtime_ns,
            after.st_ctime_ns,
        )
        if len(content) > limit or stable_fields != after_fields:
            raise ValueError(f"{label} changed while it was read")
        return content
    finally:
        os.close(descriptor)


def _walk_tree(
    descriptor: int,
    relative: PurePosixPath,
    *,
    read_contents: bool,
    exclude_infrastructure: bool,
    files: list[_FileMetadata],
    directories: list[DirectorySnapshot],
    contents: dict[str, bytes],
    depth: int,
) -> None:
    if depth > _MAX_DEPTH:
        raise ValueError("evaluation tree exceeds its nesting limit")
    entries: list[tuple[str, os.stat_result]] = []
    try:
        with os.scandir(descriptor) as iterator:
            for entry in iterator:
                if len(entries) >= _MAX_DIRECTORY_ENTRIES:
                    raise ValueError("evaluation directory has too many entries")
                entries.append((entry.name, entry.stat(follow_symlinks=False)))
    except OSError as error:
        raise ValueError("evaluation tree is unreadable") from error
    entries.sort(key=lambda item: item[0])
    for name, status in entries:
        if not name or name in {".", ".."} or "\x00" in name:
            raise ValueError("evaluation tree contains an invalid name")
        child = relative / name
        if stat.S_ISLNK(status.st_mode):
            raise ValueError(f"symlink is not allowed: {child}")
        _validate_tree_name(child)
        excluded = exclude_infrastructure and _is_infrastructure(child)
        if stat.S_ISDIR(status.st_mode):
            if excluded:
                continue
            try:
                child_descriptor = os.open(name, _DIRECTORY_FLAGS, dir_fd=descriptor)
            except OSError as error:
                raise ValueError(f"directory is unsafe: {child}") from error
            try:
                opened = os.fstat(child_descriptor)
                if (
                    not stat.S_ISDIR(opened.st_mode)
                    or _identity(opened) != _identity(status)
                    or stat.S_IMODE(opened.st_mode) != stat.S_IMODE(status.st_mode)
                ):
                    raise ValueError(f"directory changed while opening: {child}")
                directories.append(
                    DirectorySnapshot(
                        child.as_posix(),
                        stat.S_IMODE(opened.st_mode),
                    )
                )
                if len(directories) > _MAX_DIRECTORIES:
                    raise ValueError("evaluation tree exceeds its directory limit")
                _walk_tree(
                    child_descriptor,
                    child,
                    read_contents=read_contents,
                    exclude_infrastructure=exclude_infrastructure,
                    files=files,
                    directories=directories,
                    contents=contents,
                    depth=depth + 1,
                )
            finally:
                os.close(child_descriptor)
            continue
        if not stat.S_ISREG(status.st_mode) or status.st_nlink != 1:
            raise ValueError(
                f"evaluation path is not a single-link regular file: {child}"
            )
        if status.st_size > _MAX_FILE_BYTES:
            raise ValueError(f"evaluation file is too large: {child}")
        if excluded:
            continue
        path = child.as_posix()
        files.append(
            _FileMetadata(
                path,
                stat.S_IMODE(status.st_mode),
                status.st_size,
                status.st_dev,
                status.st_ino,
                status.st_mtime_ns,
                status.st_ctime_ns,
            )
        )
        if read_contents:
            contents[path] = _read_open_regular(
                descriptor,
                name,
                status,
                limit=_MAX_FILE_BYTES,
                label=path,
            )
        if (
            len(files) > _MAX_FILES
            or sum(item.size for item in files) > _MAX_TREE_BYTES
        ):
            raise ValueError("evaluation tree exceeds its file or byte limit")


def _scan_tree_metadata(
    root: Path,
) -> tuple[tuple[_FileMetadata, ...], tuple[DirectorySnapshot, ...]]:
    try:
        descriptor = os.open(root, _DIRECTORY_FLAGS)
    except OSError as error:
        raise ValueError("evaluation root must be a safe directory") from error
    try:
        files: list[_FileMetadata] = []
        directories: list[DirectorySnapshot] = []
        _walk_tree(
            descriptor,
            PurePosixPath(),
            read_contents=False,
            exclude_infrastructure=False,
            files=files,
            directories=directories,
            contents={},
            depth=0,
        )
        return tuple(sorted(files, key=lambda item: item.path)), tuple(
            sorted(directories, key=lambda item: item.path)
        )
    finally:
        os.close(descriptor)


def _tree_hash(
    files: Iterable[FileSnapshot],
    directories: Iterable[DirectorySnapshot] = (),
) -> str:
    digest = hashlib.sha256()
    for item in sorted(directories, key=lambda snapshot: snapshot.path):
        encoded = json.dumps(
            ["directory", item.path, item.mode],
            ensure_ascii=True,
            separators=(",", ":"),
        ).encode("utf-8")
        digest.update(len(encoded).to_bytes(8, "big"))
        digest.update(encoded)
    for item in sorted(files, key=lambda snapshot: snapshot.path):
        encoded = json.dumps(
            ["file", item.path, item.mode, item.size, item.sha256],
            ensure_ascii=True,
            separators=(",", ":"),
        ).encode("utf-8")
        digest.update(len(encoded).to_bytes(8, "big"))
        digest.update(encoded)
    return digest.hexdigest()


def _capture_tree(
    root: Path,
    *,
    exclude_infrastructure: bool = False,
    expected_root_identity: tuple[int, int] | None = None,
) -> _TreeCapture:
    try:
        descriptor = os.open(root, _DIRECTORY_FLAGS)
    except OSError as error:
        raise ValueError("evaluation root must be a safe directory") from error
    try:
        if (
            expected_root_identity is not None
            and _identity(os.fstat(descriptor)) != expected_root_identity
        ):
            raise ValueError("evaluation root identity changed")
        metadata: list[_FileMetadata] = []
        directories: list[DirectorySnapshot] = []
        contents: dict[str, bytes] = {}
        _walk_tree(
            descriptor,
            PurePosixPath(),
            read_contents=True,
            exclude_infrastructure=exclude_infrastructure,
            files=metadata,
            directories=directories,
            contents=contents,
            depth=0,
        )
    finally:
        os.close(descriptor)
    snapshots = tuple(
        FileSnapshot(
            item.path,
            item.mode,
            item.size,
            hashlib.sha256(contents[item.path]).hexdigest(),
        )
        for item in sorted(metadata, key=lambda value: value.path)
    )
    return _TreeCapture(
        snapshots,
        tuple(sorted(directories, key=lambda item: item.path)),
        tuple((path, contents[path]) for path in sorted(contents)),
        _tree_hash(snapshots, directories),
    )


def _read_relative(
    root: Path, relative: str, *, limit: int, label: str
) -> tuple[bytes, _FileMetadata]:
    parts = PurePosixPath(relative).parts
    if not parts:
        raise ValueError(f"{label} path is invalid")
    try:
        descriptor = os.open(root, _DIRECTORY_FLAGS)
    except OSError as error:
        raise ValueError(f"{label} parent is unsafe") from error
    try:
        for part in parts[:-1]:
            try:
                child = os.open(part, _DIRECTORY_FLAGS, dir_fd=descriptor)
            except OSError as error:
                raise ValueError(f"{label} parent is unsafe") from error
            os.close(descriptor)
            descriptor = child
        try:
            expected = os.stat(parts[-1], dir_fd=descriptor, follow_symlinks=False)
        except OSError as error:
            raise ValueError(f"{label} is missing or unsafe") from error
        if stat.S_ISLNK(expected.st_mode):
            raise ValueError(f"{label} is a symlink")
        content = _read_open_regular(
            descriptor,
            parts[-1],
            expected,
            limit=limit,
            label=label,
        )
        return content, _FileMetadata(
            relative,
            stat.S_IMODE(expected.st_mode),
            expected.st_size,
            expected.st_dev,
            expected.st_ino,
            expected.st_mtime_ns,
            expected.st_ctime_ns,
        )
    finally:
        os.close(descriptor)


def _strict_object(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for key, value in pairs:
        if key in result:
            raise ValueError(f"duplicate JSON field: {key}")
        result[key] = value
    return result


def _load_json(content: bytes, label: str) -> Any:
    def reject_constant(value: str) -> None:
        raise ValueError(f"{label} contains non-finite number {value}")

    try:
        value = json.loads(
            content.decode("utf-8"),
            object_pairs_hook=_strict_object,
            parse_constant=reject_constant,
        )
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise ValueError(f"{label} must contain strict UTF-8 JSON") from error
    except RecursionError as error:
        raise ValueError(f"{label} exceeds the JSON nesting limit") from error
    try:
        _validate_finite_json(value)
    except RecursionError as error:
        raise ValueError(f"{label} exceeds the JSON nesting limit") from error
    except ValueError as error:
        raise ValueError(f"{label} contains a non-finite number") from error
    return value


def _validate_finite_json(value: Any) -> None:
    if isinstance(value, float) and not isfinite(value):
        raise ValueError("JSON numbers must be finite")
    if isinstance(value, list):
        for item in value:
            _validate_finite_json(item)
    elif isinstance(value, dict):
        for item in value.values():
            _validate_finite_json(item)


def _normalize_relative(value: Any, label: str) -> str:
    if not isinstance(value, str) or not value or "\x00" in value or "\\" in value:
        raise ValueError(f"{label} must contain normalized relative paths")
    path = PurePosixPath(value)
    if (
        path.is_absolute()
        or path == PurePosixPath(".")
        or any(part in {"", ".", ".."} for part in path.parts)
    ):
        raise ValueError(f"{label} must contain normalized relative paths")
    if path.as_posix() != value or _is_infrastructure(path):
        raise ValueError(f"{label} must contain normalized non-internal paths")
    _validate_tree_name(path)
    return value


def _validate_manifest(value: Any) -> TaskManifest:
    if not isinstance(value, dict):
        raise ValueError("task manifest must be a JSON object")
    fields = set(value)
    if fields != _MANIFEST_FIELDS:
        missing = sorted(_MANIFEST_FIELDS - fields)
        unknown = sorted(fields - _MANIFEST_FIELDS)
        details = []
        if missing:
            details.append(f"missing {', '.join(missing)}")
        if unknown:
            details.append(f"unknown {', '.join(unknown)}")
        raise ValueError(f"task manifest fields are invalid: {'; '.join(details)}")
    if value["schema_version"] != 1 or isinstance(value["schema_version"], bool):
        raise ValueError("unsupported task manifest schema_version")
    task_id = value["id"]
    if (
        not isinstance(task_id, str)
        or not task_id.strip()
        or len(task_id) > 128
        or any(
            character not in "abcdefghijklmnopqrstuvwxyz0123456789-_"
            for character in task_id
        )
    ):
        raise ValueError("task manifest id is invalid")
    prompt = value["prompt"]
    if (
        not isinstance(prompt, str)
        or not prompt.strip()
        or len(prompt) > _MAX_STRING_CHARS
    ):
        raise ValueError("task manifest prompt is invalid")
    max_steps = value["max_steps"]
    if (
        isinstance(max_steps, bool)
        or not isinstance(max_steps, int)
        or not 1 <= max_steps <= 1_000
    ):
        raise ValueError("task manifest max_steps is invalid")
    editable = value["editable_paths"]
    if not isinstance(editable, list) or not editable or len(editable) > _MAX_FILES:
        raise ValueError("task manifest editable_paths is invalid")
    normalized = tuple(_normalize_relative(item, "editable_paths") for item in editable)
    if len(set(normalized)) != len(normalized):
        raise ValueError("task manifest editable_paths contains duplicates")
    parsed = [PurePosixPath(item) for item in normalized]
    for index, path in enumerate(parsed):
        for other in parsed[index + 1 :]:
            if path in other.parents or other in path.parents:
                raise ValueError("task manifest editable_paths overlap")
    return TaskManifest(1, task_id, prompt, max_steps, normalized)


def _create_empty_destination(
    destination: Path,
    *,
    expected_parent_identity: tuple[int, int] | None = None,
) -> tuple[Path, tuple[int, int]]:
    destination = Path(destination)
    name = destination.name
    if not name or name in {".", ".."} or "\x00" in name:
        raise ValueError("evaluation destination name is invalid")
    try:
        parent_path = destination.parent.resolve(strict=True)
        parent = os.open(parent_path, _DIRECTORY_FLAGS)
    except (OSError, RuntimeError) as error:
        raise ValueError("evaluation destination parent is unsafe") from error
    child = None
    try:
        if (
            expected_parent_identity is not None
            and _identity(os.fstat(parent)) != expected_parent_identity
        ):
            raise ValueError("evaluation destination parent identity changed")
        try:
            os.stat(name, dir_fd=parent, follow_symlinks=False)
        except FileNotFoundError:
            pass
        else:
            raise ValueError("evaluation destination must not already exist")
        os.mkdir(name, 0o700, dir_fd=parent)
        child = os.open(name, _DIRECTORY_FLAGS, dir_fd=parent)
        opened = os.fstat(child)
        named = os.stat(name, dir_fd=parent, follow_symlinks=False)
        if not stat.S_ISDIR(named.st_mode) or _identity(opened) != _identity(named):
            raise ValueError("evaluation destination changed while it was created")
        os.fsync(parent)
        return parent_path / name, _identity(opened)
    except OSError as error:
        raise ValueError(
            "evaluation destination could not be created safely"
        ) from error
    finally:
        if child is not None:
            os.close(child)
        os.close(parent)


def _canonical_new_path(destination: Path) -> Path:
    destination = Path(destination)
    name = destination.name
    if not name or name in {".", ".."} or "\x00" in name:
        raise ValueError("evaluation destination name is invalid")
    try:
        return destination.parent.resolve(strict=True) / name
    except (OSError, RuntimeError) as error:
        raise ValueError("evaluation destination parent is unsafe") from error


def _paths_overlap(first: Path, second: Path) -> bool:
    return first == second or first in second.parents or second in first.parents


def _open_destination_directory(
    root: int, parts: tuple[str, ...], *, create: bool
) -> int:
    descriptor = os.dup(root)
    try:
        for part in parts:
            if create:
                try:
                    os.mkdir(part, 0o700, dir_fd=descriptor)
                    os.fsync(descriptor)
                except FileExistsError:
                    pass
            child = os.open(part, _DIRECTORY_FLAGS, dir_fd=descriptor)
            os.close(descriptor)
            descriptor = child
        return descriptor
    except BaseException:
        os.close(descriptor)
        raise


def _copy_capture(
    capture: _TreeCapture,
    destination: Path,
    expected_root_identity: tuple[int, int],
) -> None:
    try:
        root = os.open(destination, _DIRECTORY_FLAGS)
    except OSError as error:
        raise ValueError("staging destination is unsafe") from error
    try:
        if _identity(os.fstat(root)) != expected_root_identity:
            raise ValueError("staging destination identity changed")
        for snapshot in capture.directories:
            try:
                directory = _open_destination_directory(
                    root,
                    PurePosixPath(snapshot.path).parts,
                    create=True,
                )
            except OSError as error:
                raise ValueError(
                    f"could not create staged directory {snapshot.path}"
                ) from error
            os.close(directory)
        snapshots = {item.path: item for item in capture.files}
        flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0)
        for relative, content in capture.contents:
            path = PurePosixPath(relative)
            parent = None
            try:
                parent = _open_destination_directory(
                    root,
                    path.parent.parts if path.parent != PurePosixPath(".") else (),
                    create=False,
                )
                descriptor = os.open(
                    path.name,
                    flags,
                    snapshots[relative].mode,
                    dir_fd=parent,
                )
            except OSError as error:
                if parent is not None:
                    os.close(parent)
                raise ValueError(f"could not create staged file {relative}") from error
            try:
                offset = 0
                while offset < len(content):
                    written = os.write(descriptor, content[offset:])
                    if written <= 0:
                        raise ValueError(f"could not write staged file {relative}")
                    offset += written
                os.fchmod(descriptor, snapshots[relative].mode)
                os.fsync(descriptor)
                os.fsync(parent)
            finally:
                os.close(descriptor)
                os.close(parent)
        for snapshot in sorted(
            capture.directories,
            key=lambda item: (len(PurePosixPath(item.path).parts), item.path),
            reverse=True,
        ):
            directory = None
            try:
                directory = _open_destination_directory(
                    root,
                    PurePosixPath(snapshot.path).parts,
                    create=False,
                )
                os.fchmod(directory, snapshot.mode)
                os.fsync(directory)
            except OSError as error:
                raise ValueError(
                    f"could not preserve staged directory mode {snapshot.path}"
                ) from error
            finally:
                if directory is not None:
                    os.close(directory)
        os.fsync(root)
    finally:
        os.close(root)


@dataclass(frozen=True)
class TaskPackage:
    """A validated package whose held-out check bytes remain unopened."""

    root: Path
    manifest: TaskManifest
    _workspace_capture: _TreeCapture
    _held_out_metadata: _FileMetadata

    @classmethod
    def load(cls, root: Path) -> "TaskPackage":
        root = Path(root)
        metadata, directories = _scan_tree_metadata(root)
        paths = {item.path for item in metadata}
        directory_paths = {item.path for item in directories}
        top_level = {path.split("/", 1)[0] for path in (*paths, *directory_paths)}
        if top_level != _PACKAGE_TOP_LEVEL:
            unexpected = sorted(top_level - _PACKAGE_TOP_LEVEL)
            missing = sorted(_PACKAGE_TOP_LEVEL - top_level)
            raise ValueError(
                "unexpected package entries or missing required entries: "
                f"unexpected={unexpected}, missing={missing}"
            )
        if "task.json" not in paths or "held_out_tests/checks.json" not in paths:
            raise ValueError("package task.json or held-out checks are missing")
        if (
            "workspace" not in directory_paths
            or "held_out_tests" not in directory_paths
        ):
            raise ValueError("package workspace or held_out_tests directory is missing")
        held_entries = {
            path for path in paths if path.startswith("held_out_tests/")
        } | {path for path in directory_paths if path.startswith("held_out_tests/")}
        if held_entries != {"held_out_tests/checks.json"}:
            raise ValueError("unexpected held-out grader entry")
        root_files = {path for path in paths if "/" not in path}
        if root_files != {"task.json"}:
            raise ValueError("unexpected package file")
        metadata_by_path = {item.path: item for item in metadata}
        for protected in ("task.json", "held_out_tests/checks.json"):
            if metadata_by_path[protected].mode & _EXECUTABLE_BITS:
                raise ValueError(f"{protected} must not be executable")
        manifest_bytes, manifest_metadata = _read_relative(
            root,
            "task.json",
            limit=_MAX_FILE_BYTES,
            label="task.json",
        )
        if manifest_metadata != metadata_by_path["task.json"]:
            raise ValueError("task.json changed during package validation")
        manifest = _validate_manifest(_load_json(manifest_bytes, "task.json"))
        workspace = _capture_tree(root / "workspace")
        if any(
            _is_infrastructure(PurePosixPath(path))
            for path in (
                *(item.path for item in workspace.files),
                *(item.path for item in workspace.directories),
            )
        ):
            raise ValueError("package workspace contains protected evaluator state")
        return cls(
            root.resolve(),
            manifest,
            workspace,
            metadata_by_path["held_out_tests/checks.json"],
        )

    def stage(self, destination: Path) -> "StagedTask":
        intended = _canonical_new_path(destination)
        if _paths_overlap(intended, self.root):
            raise ValueError("staging destination must not overlap the task package")
        destination, destination_identity = _create_empty_destination(destination)
        workspace, workspace_identity = _create_empty_destination(
            destination / "workspace",
            expected_parent_identity=destination_identity,
        )
        _copy_capture(self._workspace_capture, workspace, workspace_identity)
        copied = _capture_tree(
            workspace,
            expected_root_identity=workspace_identity,
        )
        if (
            copied.files != self._workspace_capture.files
            or copied.directories != self._workspace_capture.directories
            or copied.contents != self._workspace_capture.contents
        ):
            raise ValueError("staged workspace does not match the sealed package")
        return StagedTask(
            self,
            destination,
            workspace,
            copied.files,
            copied.directories,
            copied.tree_sha256,
            workspace_identity,
            destination_identity,
        )


@dataclass(frozen=True)
class StagedTask:
    """The public agent workspace and its initial sealed snapshot."""

    package: TaskPackage
    destination: Path
    workspace: Path
    initial_files: tuple[FileSnapshot, ...]
    initial_directories: tuple[DirectorySnapshot, ...]
    initial_tree_sha256: str
    _workspace_identity: tuple[int, int]
    _destination_identity: tuple[int, int]

    def freeze(self, destination: Path) -> CandidateSnapshot:
        intended = _canonical_new_path(destination)
        if _paths_overlap(intended, self.workspace) or _paths_overlap(
            intended, self.package.root
        ):
            raise ValueError(
                "candidate destination must not overlap the package or live workspace"
            )
        capture = _capture_tree(
            self.workspace,
            exclude_infrastructure=True,
            expected_root_identity=self._workspace_identity,
        )
        expected_parent_identity = (
            self._destination_identity
            if Path(destination).parent == self.destination
            else None
        )
        destination, destination_identity = _create_empty_destination(
            destination,
            expected_parent_identity=expected_parent_identity,
        )
        _copy_capture(capture, destination, destination_identity)
        copied = _capture_tree(
            destination,
            expected_root_identity=destination_identity,
        )
        if (
            copied.files != capture.files
            or copied.directories != capture.directories
            or copied.contents != capture.contents
        ):
            raise ValueError("frozen candidate does not match the staged workspace")
        return CandidateSnapshot(
            destination,
            self.package.manifest.id,
            copied.files,
            copied.directories,
            copied.tree_sha256,
            self.initial_tree_sha256,
            copied.contents,
        )


def _check_fields(check_type: str) -> set[str]:
    common = {"type", "name", "path"}
    if check_type in {"path_exists", "path_absent", "unchanged"}:
        return common
    if check_type == "text_equals":
        return common | {"expected"}
    if check_type == "json_value":
        return common | {"pointer", "expected"}
    if check_type == "python_constant":
        return common | {"constant", "expected"}
    raise ValueError(f"unsupported held-out check type: {check_type}")


def _validate_checks(value: Any) -> tuple[dict[str, Any], ...]:
    if not isinstance(value, dict) or set(value) != {"schema_version", "checks"}:
        raise ValueError("held-out checks must use the exact versioned schema")
    if value["schema_version"] != 1 or isinstance(value["schema_version"], bool):
        raise ValueError("unsupported held-out checks schema_version")
    raw_checks = value["checks"]
    if (
        not isinstance(raw_checks, list)
        or not raw_checks
        or len(raw_checks) > _MAX_CHECKS
    ):
        raise ValueError("held-out checks must be a non-empty bounded array")
    validated: list[dict[str, Any]] = []
    names: set[str] = set()
    for raw in raw_checks:
        if not isinstance(raw, dict):
            raise ValueError("each held-out check must be an object")
        check_type = raw.get("type")
        if not isinstance(check_type, str):
            raise ValueError("held-out check type is invalid")
        if set(raw) != _check_fields(check_type):
            raise ValueError(f"held-out check fields are invalid for {check_type}")
        name = raw["name"]
        if not isinstance(name, str) or not name.strip() or len(name) > 256:
            raise ValueError("held-out check name is invalid")
        if name in names:
            raise ValueError("held-out check names must be unique")
        names.add(name)
        detached = dict(raw)
        detached["path"] = _normalize_relative(raw["path"], "held-out check path")
        if check_type == "text_equals" and (
            not isinstance(raw["expected"], str)
            or len(raw["expected"]) > _MAX_STRING_CHARS
        ):
            raise ValueError("text_equals expected value is invalid")
        if check_type == "json_value":
            pointer = raw["pointer"]
            if not isinstance(pointer, str) or len(pointer) > 4_096:
                raise ValueError("json_value pointer is invalid")
            _pointer_parts(pointer)
        if check_type == "python_constant":
            constant = raw["constant"]
            if (
                not isinstance(constant, str)
                or not constant.isidentifier()
                or len(constant) > 256
            ):
                raise ValueError("python_constant constant is invalid")
        validated.append(detached)
    return tuple(sorted(validated, key=lambda check: check["name"]))


def _pointer_parts(pointer: str) -> tuple[str, ...]:
    if pointer == "":
        return ()
    if not pointer.startswith("/"):
        raise ValueError("JSON pointer must be empty or start with /")
    parts = []
    for encoded in pointer[1:].split("/"):
        index = 0
        decoded = []
        while index < len(encoded):
            if encoded[index] != "~":
                decoded.append(encoded[index])
                index += 1
                continue
            if index + 1 >= len(encoded) or encoded[index + 1] not in {"0", "1"}:
                raise ValueError("JSON pointer contains an invalid escape")
            decoded.append("~" if encoded[index + 1] == "0" else "/")
            index += 2
        parts.append("".join(decoded))
    return tuple(parts)


def _json_pointer(value: Any, pointer: str) -> Any:
    current = value
    for part in _pointer_parts(pointer):
        if isinstance(current, dict):
            if part not in current:
                raise KeyError(part)
            current = current[part]
        elif isinstance(current, list):
            if not part.isdigit() or (len(part) > 1 and part.startswith("0")):
                raise KeyError(part)
            index = int(part)
            if index >= len(current):
                raise KeyError(part)
            current = current[index]
        else:
            raise KeyError(part)
    return current


def _json_equal(left: Any, right: Any) -> bool:
    if isinstance(left, bool) or isinstance(right, bool):
        return type(left) is type(right) and left == right
    if isinstance(left, (int, float)) and isinstance(right, (int, float)):
        return left == right
    if type(left) is not type(right):
        return False
    if isinstance(left, list):
        return len(left) == len(right) and all(
            _json_equal(a, b) for a, b in zip(left, right, strict=True)
        )
    if isinstance(left, dict):
        return set(left) == set(right) and all(
            _json_equal(left[key], right[key]) for key in left
        )
    return left == right


def _ast_json_literal(node: ast.AST) -> Any:
    if isinstance(node, ast.Constant) and (
        node.value is None or isinstance(node.value, (bool, int, float, str))
    ):
        if isinstance(node.value, float) and not isfinite(node.value):
            raise ValueError("Python numeric literal must be finite")
        return node.value
    if isinstance(node, (ast.List, ast.Tuple)):
        return [_ast_json_literal(item) for item in node.elts]
    if isinstance(node, ast.Dict):
        result: dict[str, Any] = {}
        for key_node, value_node in zip(node.keys, node.values, strict=True):
            if not isinstance(key_node, ast.Constant) or not isinstance(
                key_node.value, str
            ):
                raise ValueError("Python literal dictionary keys must be strings")
            if key_node.value in result:
                raise ValueError("Python literal dictionary keys must be unique")
            result[key_node.value] = _ast_json_literal(value_node)
        return result
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub)):
        value = _ast_json_literal(node.operand)
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError("Python unary literal must be numeric")
        return value if isinstance(node.op, ast.UAdd) else -value
    raise ValueError("Python constant is not a supported JSON literal")


def _python_constant(content: bytes, name: str) -> Any:
    text = content.decode("utf-8")
    module = ast.parse(text, mode="exec")
    values: list[ast.AST] = []
    for statement in module.body:
        if isinstance(statement, ast.Assign) and len(statement.targets) == 1:
            target = statement.targets[0]
            if isinstance(target, ast.Name) and target.id == name:
                values.append(statement.value)
        elif (
            isinstance(statement, ast.AnnAssign)
            and isinstance(statement.target, ast.Name)
            and statement.target.id == name
            and statement.value is not None
        ):
            values.append(statement.value)
    if len(values) != 1:
        raise ValueError("Python constant must have exactly one direct assignment")
    return _ast_json_literal(values[0])


def _allowed_path(path: str, editable_paths: tuple[str, ...]) -> bool:
    candidate = PurePosixPath(path)
    return any(
        candidate == PurePosixPath(editable)
        or PurePosixPath(editable) in candidate.parents
        for editable in editable_paths
    )


def _validate_file_snapshot(item: Any, label: str) -> None:
    if not isinstance(item, FileSnapshot):
        raise ValueError(f"{label} contains an invalid file snapshot")
    _normalize_relative(item.path, label)
    if (
        isinstance(item.mode, bool)
        or not isinstance(item.mode, int)
        or not 0 <= item.mode <= 0o7777
        or isinstance(item.size, bool)
        or not isinstance(item.size, int)
        or not 0 <= item.size <= _MAX_FILE_BYTES
        or not isinstance(item.sha256, str)
        or len(item.sha256) != 64
        or any(character not in "0123456789abcdef" for character in item.sha256)
    ):
        raise ValueError(f"{label} contains invalid file metadata")


def _validate_directory_snapshot(item: Any, label: str) -> None:
    if not isinstance(item, DirectorySnapshot):
        raise ValueError(f"{label} contains invalid directory metadata")
    _normalize_relative(item.path, label)
    if (
        isinstance(item.mode, bool)
        or not isinstance(item.mode, int)
        or not 0 <= item.mode <= 0o7777
    ):
        raise ValueError(f"{label} contains invalid directory metadata")


def _validate_snapshot_nodes(
    files: Any,
    directories: Any,
    *,
    contents: Any | None,
    label: str,
) -> None:
    if not isinstance(files, tuple) or len(files) > _MAX_FILES:
        raise ValueError(f"{label} file list is invalid")
    if not isinstance(directories, tuple) or len(directories) > _MAX_DIRECTORIES:
        raise ValueError(f"{label} directory list is invalid")
    for item in files:
        _validate_file_snapshot(item, label)
    for item in directories:
        _validate_directory_snapshot(item, label)
    file_paths = tuple(item.path for item in files)
    if file_paths != tuple(sorted(file_paths)) or len(set(file_paths)) != len(
        file_paths
    ):
        raise ValueError(f"{label} file paths must be unique and sorted")
    directory_paths = tuple(item.path for item in directories)
    if directory_paths != tuple(sorted(directory_paths)) or len(
        set(directory_paths)
    ) != len(directory_paths):
        raise ValueError(f"{label} directory paths must be unique and sorted")
    directory_path_set = set(directory_paths)
    if set(file_paths) & directory_path_set:
        raise ValueError(f"{label} path cannot be both a file and directory")
    all_paths = set(file_paths) | directory_path_set
    for path in all_paths:
        parent = PurePosixPath(path).parent
        while parent != PurePosixPath("."):
            if parent.as_posix() not in directory_path_set:
                raise ValueError(f"{label} has a missing parent directory")
            parent = parent.parent
    if contents is None:
        return
    if not isinstance(contents, tuple):
        raise ValueError(f"{label} contents are invalid")
    content_paths: list[str] = []
    content_map: dict[str, bytes] = {}
    for item in contents:
        if (
            not isinstance(item, tuple)
            or len(item) != 2
            or not isinstance(item[0], str)
            or not isinstance(item[1], bytes)
        ):
            raise ValueError(f"{label} contents are invalid")
        path, content = item
        content_paths.append(path)
        if path in content_map:
            raise ValueError(f"{label} content paths must be unique")
        content_map[path] = content
    if tuple(content_paths) != tuple(sorted(file_paths)):
        raise ValueError(f"{label} contents do not match its file list")
    if sum(len(content) for content in content_map.values()) > _MAX_TREE_BYTES:
        raise ValueError(f"{label} contents exceed the byte limit")
    for snapshot in files:
        content = content_map[snapshot.path]
        if (
            len(content) != snapshot.size
            or hashlib.sha256(content).hexdigest() != snapshot.sha256
        ):
            raise ValueError(f"{label} contents do not match its file metadata")


def _validate_staged_snapshot(staged: StagedTask) -> None:
    if not isinstance(staged, StagedTask) or not isinstance(
        staged.package, TaskPackage
    ):
        raise ValueError("staged task has an invalid type")
    _validate_snapshot_nodes(
        staged.initial_files,
        staged.initial_directories,
        contents=None,
        label="initial snapshot",
    )
    package_capture = staged.package._workspace_capture
    if (
        staged.initial_files != package_capture.files
        or staged.initial_directories != package_capture.directories
        or staged.initial_tree_sha256 != package_capture.tree_sha256
        or staged.initial_tree_sha256
        != _tree_hash(staged.initial_files, staged.initial_directories)
    ):
        raise ValueError("staged task initial snapshot is inconsistent")


def _validate_candidate_snapshot(
    staged: StagedTask, candidate: CandidateSnapshot
) -> None:
    _validate_staged_snapshot(staged)
    if not isinstance(candidate, CandidateSnapshot):
        raise ValueError("candidate snapshot has an invalid type")
    _validate_snapshot_nodes(
        candidate.files,
        candidate.directories,
        contents=candidate._contents,
        label="candidate snapshot",
    )
    if (
        candidate.task_id != staged.package.manifest.id
        or candidate.initial_tree_sha256 != staged.initial_tree_sha256
        or candidate.tree_sha256 != _tree_hash(candidate.files, candidate.directories)
    ):
        raise ValueError("candidate snapshot seal is inconsistent")


def _forbidden_modifications(
    staged: StagedTask, candidate: CandidateSnapshot
) -> tuple[str, ...]:
    initial: dict[str, tuple[str, FileSnapshot | DirectorySnapshot]] = {
        item.path: ("file", item) for item in staged.initial_files
    }
    initial.update(
        {item.path: ("directory", item) for item in staged.initial_directories}
    )
    final: dict[str, tuple[str, FileSnapshot | DirectorySnapshot]] = {
        item.path: ("file", item) for item in candidate.files
    }
    final.update({item.path: ("directory", item) for item in candidate.directories})
    changed = {
        path
        for path in set(initial) | set(final)
        if initial.get(path) != final.get(path)
    }
    return tuple(
        sorted(
            path
            for path in changed
            if not _allowed_path(path, staged.package.manifest.editable_paths)
        )
    )


def _evaluate_check(
    check: dict[str, Any],
    *,
    initial: dict[str, FileSnapshot],
    files: dict[str, FileSnapshot],
    directories: set[str],
    contents: dict[str, bytes],
) -> CheckResult:
    check_type = check["type"]
    name = check["name"]
    path = check["path"]
    passed = False
    detail = "condition not satisfied"
    try:
        if check_type == "path_exists":
            passed = path in files
        elif check_type == "path_absent":
            passed = path not in files and path not in directories
        elif check_type == "unchanged":
            passed = path in initial and initial[path] == files.get(path)
        elif check_type == "text_equals":
            passed = contents[path].decode("utf-8") == check["expected"]
        elif check_type == "json_value":
            parsed = _load_json(contents[path], f"candidate {path}")
            actual = _json_pointer(parsed, check["pointer"])
            passed = _json_equal(actual, check["expected"])
        elif check_type == "python_constant":
            actual = _python_constant(contents[path], check["constant"])
            passed = _json_equal(actual, check["expected"])
        if passed:
            detail = "passed"
    except (KeyError, RecursionError, UnicodeDecodeError, SyntaxError, ValueError):
        passed = False
        detail = "candidate content could not satisfy the static check"
    return CheckResult(name, check_type, passed, detail)


class StaticHeldOutGrader:
    """Grade only allowlisted declarative checks over frozen candidate bytes."""

    def grade(self, staged: StagedTask, candidate: CandidateSnapshot) -> GradeReport:
        candidate_hash = (
            candidate.tree_sha256
            if isinstance(candidate, CandidateSnapshot)
            and isinstance(candidate.tree_sha256, str)
            else "invalid"
        )
        try:
            _validate_candidate_snapshot(staged, candidate)
            forbidden = _forbidden_modifications(staged, candidate)
        except (AttributeError, RecursionError, TypeError, ValueError) as error:
            return GradeReport(
                "error",
                (),
                (),
                candidate_hash,
                str(error),
            )
        try:
            content, metadata = _read_relative(
                staged.package.root,
                "held_out_tests/checks.json",
                limit=_MAX_FILE_BYTES,
                label="held-out checks",
            )
            if metadata != staged.package._held_out_metadata:
                raise ValueError("held-out checks changed after package validation")
            if metadata.mode & _EXECUTABLE_BITS:
                raise ValueError("held-out checks must not be executable")
            checks = _validate_checks(_load_json(content, "held-out checks"))
        except (OSError, RecursionError, ValueError) as error:
            return GradeReport(
                "error",
                (),
                forbidden,
                candidate.tree_sha256,
                str(error),
            )
        initial = {item.path: item for item in staged.initial_files}
        files = {item.path: item for item in candidate.files}
        contents = dict(candidate._contents)
        outcomes = tuple(
            _evaluate_check(
                check,
                initial=initial,
                files=files,
                directories={item.path for item in candidate.directories},
                contents=contents,
            )
            for check in checks
        )
        passed = not forbidden and all(outcome.passed for outcome in outcomes)
        return GradeReport(
            "passed" if passed else "failed",
            outcomes,
            forbidden,
            candidate.tree_sha256,
        )


def _optional_sum(events: tuple[Any, ...], field: str) -> int | None:
    assistant_events = tuple(
        event for event in events if event.type == "assistant_message"
    )
    if not assistant_events:
        return None
    values = []
    for event in assistant_events:
        generation = event.data.get("generation")
        if not isinstance(generation, dict):
            return None
        value = generation.get(field)
        if not isinstance(value, int) or isinstance(value, bool) or value < 0:
            return None
        values.append(value)
    return sum(values)


def _latest_run_events(events: tuple[Any, ...]) -> tuple[Any, ...]:
    starts = [
        index for index, event in enumerate(events) if event.type == "run_started"
    ]
    if not starts:
        return events
    start = starts[-1]
    end = next(
        (
            index + 1
            for index in range(start, len(events))
            if events[index].type == "run_finished"
        ),
        len(events),
    )
    return events[start:end]


def aggregate_metrics(
    session: SessionLog,
    agent_run: AgentRun,
    wall_time_seconds: float,
) -> EvaluationMetrics:
    """Reconstruct comparable metrics from durable events, preserving unknowns."""

    wall_time = float(wall_time_seconds)
    if not isfinite(wall_time) or wall_time < 0:
        raise ValueError("evaluation wall time must be finite and non-negative")
    events = _latest_run_events(session.events)
    durable_reasons = [
        event.data.get("reason") for event in events if event.type == "run_finished"
    ]
    terminal_reason = agent_run.reason
    if durable_reasons:
        durable_reason = durable_reasons[-1]
        if not isinstance(durable_reason, str) or durable_reason != agent_run.reason:
            raise ValueError("durable terminal reason does not match the agent run")
        terminal_reason = durable_reason
    assistant_events = tuple(
        event for event in events if event.type == "assistant_message"
    )
    tool_results = tuple(event for event in events if event.type == "tool_result")
    latencies: list[float] = []
    visible_bytes: list[int] = []
    latency_known = bool(assistant_events)
    visible_bytes_known = bool(assistant_events)
    for event in assistant_events:
        generation = event.data.get("generation")
        if isinstance(generation, dict):
            latency = generation.get("latency_seconds")
            if (
                isinstance(latency, (int, float))
                and not isinstance(latency, bool)
                and latency >= 0
                and isfinite(float(latency))
            ):
                latencies.append(float(latency))
            else:
                latency_known = False
        else:
            latency_known = False
        context = event.data.get("context")
        if isinstance(context, dict):
            value = context.get("visible_tool_result_bytes")
            if isinstance(value, int) and not isinstance(value, bool) and value >= 0:
                visible_bytes.append(value)
            else:
                visible_bytes_known = False
        else:
            visible_bytes_known = False
    malformed = sum(
        1
        for event in tool_results
        if event.data.get("tool_call_id") is None
        and event.data.get("assistant_event_id") is None
        and event.data.get("tool") is None
        and event.data.get("is_error") is True
    )
    return EvaluationMetrics(
        model_turns=len(assistant_events),
        tool_calls=sum(1 for event in events if event.type == "tool_call"),
        malformed_actions=malformed,
        tool_errors=sum(
            1
            for event in tool_results
            if isinstance(event.data.get("tool_call_id"), str)
            and event.data.get("is_error") is True
        ),
        input_tokens=_optional_sum(events, "input_tokens"),
        output_tokens=_optional_sum(events, "output_tokens"),
        reused_tokens=_optional_sum(events, "reused_tokens"),
        rewound_tokens=_optional_sum(events, "rewound_tokens"),
        prefilled_tokens=_optional_sum(events, "prefilled_tokens"),
        visible_tool_result_bytes=(sum(visible_bytes) if visible_bytes_known else None),
        compactions=sum(1 for event in events if event.type == "compaction"),
        generation_latency_seconds=(sum(latencies) if latency_known else None),
        wall_time_seconds=wall_time,
        terminal_reason=terminal_reason,
    )


def evaluate_task(
    staged: StagedTask,
    generate: Generate,
    *,
    model: str = "evaluation",
    session: SessionLog | None = None,
    limits: AgentLimits | None = None,
    confirm_tool: Callable[[ToolAction], bool] | None = None,
    clock: Callable[[], float] = perf_counter,
) -> EvaluatedRun:
    """Run a command-free agent, freeze its bytes, then reveal static checks."""

    _validate_staged_snapshot(staged)
    started = clock()
    candidate_destination = staged.destination / "candidate"
    if os.path.lexists(candidate_destination):
        raise ValueError("staged task already has a frozen candidate")
    policy = ToolPolicy(staged.workspace, allow_writes=True, allowed_commands=())
    if policy._root_identity != staged._workspace_identity:
        raise ValueError("staged workspace identity changed before evaluation")
    if session is None:
        session = SessionStore(
            staged.workspace,
            model,
            expected_workspace_identity=staged._workspace_identity,
        ).create()
    elif session.workspace != staged.workspace.resolve():
        raise ValueError("evaluation session belongs to a different workspace")
    elif session.path is None:
        raise ValueError("evaluation requires a durable session log")
    if any(
        event.type in {"evaluation_started", "evaluation_result"}
        for event in session.events
    ):
        raise ValueError("evaluation sessions are single-use; restage the task")
    requested = limits or AgentLimits(max_steps=staged.package.manifest.max_steps)
    bounded = replace(
        requested,
        max_steps=min(requested.max_steps, staged.package.manifest.max_steps),
    )
    workspace = Workspace(
        policy,
        confirm_tool=confirm_tool,
        session_log=session,
    )
    agent_run = run_agent(
        staged.package.manifest.prompt,
        generate,
        workspace,
        bounded,
        session=session,
    )
    candidate = staged.freeze(candidate_destination)
    session.append(
        "evaluation_started",
        task_id=staged.package.manifest.id,
        candidate_tree_sha256=candidate.tree_sha256,
    )
    grade = StaticHeldOutGrader().grade(staged, candidate)
    task_success = grade.status == "passed"
    agent_run = replace(agent_run, task_success=task_success)
    metrics = aggregate_metrics(session, agent_run, clock() - started)
    session.append(
        "evaluation_result",
        task_id=staged.package.manifest.id,
        candidate_tree_sha256=candidate.tree_sha256,
        grade=asdict(grade),
        metrics=asdict(metrics),
        task_success=task_success,
    )
    return EvaluatedRun(agent_run, candidate, grade, metrics, task_success)


